  extra='\n<Section kind="math">\n'+marker+'\n\n'+bodies[i]+'\n\n'+ '\n\n'.join('<Formula value={'+json.dumps(f)+'} />' for f in formulas)+'\n\n'+symbols[i]+'\n</Section>\n'
  p.write_text(s+extra)
